# Private functions
  @fn resetEdit()  @ 28
  -- DRAW
  @fn rectFor(key)  @ 59-65
  @fn withAlpha(rgba, a)  @ 74
  @fn tagSide()  @ 77
      -- Side of a square edit-tag box: the symbol plus a 2px moat and the 1px border.
  @fn layoutCluster(keys, withAdd, sep)  @ 81-106
      -- Lay out a shortcut's chips (separator-joined, one per binding) into geometry for
      -- drawCluster: total width + each chip's {w, cells}; word runs share one cell, symbols one each.
  @fn crispBorder(x0, y0, x1, y1, colour)  @ 110-115
      -- Pixel-crisp 1px border (painter.border's 4-strip technique) on the foreground
      -- drawlist the overlay uses: painter binds to the window drawlist, behind the dim.
  @fn drawTag(cx, cy, symbol, ink, captureHere, hit)  @ 119-140
      -- Square edit tag at (cx, cy): fill + 1px border, symbol in a 2px moat (+ as
      -- 1px strips, x as diagonal). `captureHere` highlights; `hit` rect filled here.
  @fn drawCluster(row, x, y)  @ 144-184
      -- Records a click hit per chip; in edit mode also draws the ✕ corner tags and the
      -- trailing + tag, each with its own hit. See docs/help.md § Editing.
  @fn cmdLabel(cmd)  @ 188
      -- A command's human label comes from its manifest entry, wherever it is declared:
      -- a conflict's victim may live on a scope this page never shows.
  @fn chordOf(name)  @ 191-194
      -- A command's first chord, or an em dash where an override left it unbound.
  @fn familyRow(family)  @ 198-203
      -- A generated family reads as one row: its own label, and its first and last member's
      -- chords with a dash between. See docs/help.md § A generated family.
  @fn commandRow(entry)  @ 205-210
  @fn layoutBox(title, entries)  @ 214-234
      -- A group's box geometry in one pass: rows (each with a laid-out cluster) plus the box
      -- w/h, sized to the wider of title vs the shortcut column + widest label.
  @fn drawBox(box, x, y)  @ 236-247
  @fn drawConflict(winX, winY, winW, winH)  @ 253-301
      -- Centred modal for a chord collision: warn offers Cancel/Reassign, refuse reports the
      -- chord blocking a family's mask, recover narrates the loss while pollCapture reclaims.
  @fn placePins(pins, winX, winW)  @ 305-338
      -- Pin callouts sit just under their toolbar segment. Overlapping neighbours are
      -- slid to minimise total displacement — isotonic regression. See docs/help.md.
  @fn placeFlow(flows)  @ 342-359
      -- Flow groups fill their grid rect row-major: left to right, wrapping down a row
      -- at the rect's right edge. Each anchor rect carries its own cursor.
  @fn buildDismissKeys()  @ 362-377
  @fn anyKeyPressed()  @ 381-388
      -- Char queue catches punctuation/layout-specific keys; the explicit list covers
      -- the non-printables (and alphanumerics, since the macOS char queue drops some).
  @fn insideAnyBox(mouseX, mouseY)  @ 390-396
  -- EDIT MODE
  @fn buildSpec(key, mods)  @ 401-408
      -- A pressed non-modifier key plus the live modifier mask, as a cmgr keyspec.
  @fn rebindWithout(cmd, drop, add)  @ 411-418
      -- Rewrites cmd's bindings: drop `drop` (a spec ref, or nil), append `add` (or nil).
  @fn dropChord(cmd, spec)  @ 422-430
      -- Drops every binding of cmd whose chord matches spec, then rebinds. The victim's
      -- stored ref isn't the captured one, so match by resolved key+mods, not identity.
  @fn commitFamily(family, spec)  @ 434-439
      -- A family takes the captured chord's modifier mask, and only where every chord it
      -- would claim is free. See docs/help.md § A generated family.
  @fn commitCapture(spec)  @ 443-454
      -- A captured chord that collides with a reachable command opens the warn prompt;
      -- a free chord binds straight away. See docs/help.md § Editing bindings.
  @fn reassign()  @ 458-464
      -- Reassign: strip the chord from the victim, give it to cmd, then drop the victim
      -- into a recovery capture so it can claim a new chord (Esc leaves it unbound).
  @fn pollCapture()  @ 466-476
  @fn hitAt(mouseX, mouseY)  @ 479-487
      -- ✕ sits atop its chip, so a remove hit wins over the chip hit it overlaps.
  @fn handleConflict()  @ 491-506
      -- Warn-phase input: Esc/Cancel abandons untouched, Enter or the Reassign button
      -- commits. Off-button clicks are swallowed (modal), never dismissing the sheet.
  @fn handleRefusal()  @ 510-512
      -- The refusal prompt is an acknowledgement: any key or click clears it, and the
      -- gesture is swallowed rather than dismissing the sheet.
  @fn handleClicks()  @ 514-528

